SELECT p.gender, CASE WHEN p.gender = 'M' THEN CASE WHEN a.age BETWEEN 72 AND 82 THEN CASE WHEN i.intime IS NOT NULL THEN 'ICU' ELSE 'Non-ICU' END END AS careunit, a.age, COUNT(d.icd_code) AS comorbidity_count, SUM(CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS in_hospital_deaths, AVG(a.los) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.gender = 'M' AND a.age BETWEEN 77 AND 78 AND d.icd_code = '415085' GROUP BY p.gender, careunit, a.age ORDER BY p.gender, careunit, a.age NULLS LAST;